import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Object3D, Color } from 'three/webgpu';
import { texture, uv, vec4, mix, float } from 'three/tsl';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new Object3D();
  group.name = 'hub-pricing-title';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 3.2;
  const height = 2.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  let map = null;
  try {
    map = ctx.textureLoader('/prism-mock/home/nodes/cta-hero-isolated.png');
  } catch (e) {
    map = null;
  }

  if (map) {
    map.colorSpace = 'srgb';
    const texNode = texture(map, uv());
    const inkColor = vec4(new Color('#16161d'), 1.0);
    const gradientMix = mix(inkColor, texNode, float(0.85));
    material.colorNode = gradientMix;
  } else {
    material.colorNode = vec4(new Color('#16161d'), 1.0);
  }

  const plane = new Mesh(geometry, material);
  plane.name = 'pricing-title-plane';
  group.add(plane);

  let textMesh = null;
  try {
    textMesh = createText({
      text: 'Pricing',
      font: 'Lora',
      weight: 400,
      size: 0.34,
      color: '#e8ecf2',
      atlas: ctx.fontAtlas,
    });
    textMesh.name = 'pricing-title-text';
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  } catch (e) {
    textMesh = null;
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh && textMesh.userData && typeof textMesh.userData.cleanup === 'function') {
      textMesh.userData.cleanup();
    }
  };

  return group;
}
